contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address _log) public {
        require(_log != address(0));

        bool revertedBefore;
        c.SetLogFile(_log); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedBefore = true;
        } else {
            revertedBefore = false;
        }

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool revertedAfter;
        c.SetLogFile(_log); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            revertedAfter = true;
        } else {
            revertedAfter = false;
        }

        assert(!revertedBefore && revertedAfter);
    }
}

